<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {Button,Input,NativeSelect,StatusNotice,Popover,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {useManagementRequest} from './management-request';
import type {KnowledgeHistory,KnowledgeHistoryRecord,KnowledgeIndex,KnowledgeDiff,KnowledgeChange} from './knowledge-model';
const props=defineProps<{agentId:string;projectId:string;activeSnapshot?:string;activeCommit?:string;renderedSnapshot?:string;follow?:boolean;overview?:boolean;prepareData?:(index:KnowledgeIndex)=>Promise<void>;presentFrame?:(index:KnowledgeIndex,diff:KnowledgeDiff,follow:boolean,valid:()=>boolean)=>Promise<void>}>(),emit=defineEmits<{playing:[value:boolean];stop:[];'update:follow':[value:boolean];'update:overview':[value:boolean];snapshot:[index:KnowledgeIndex];prefetch:[index:KnowledgeIndex];latest:[];open:[snapshotId:string,path:string];compare:[before:string|undefined,after:string,path:string,previousPath?:string]}>();
const context=useHostContext(),request=useManagementRequest(context,()=>props.agentId),safe=(v:unknown)=>context.value.host.redact(String(v??''));
const collapsed=ref(false),moreOpen=ref(false),collapseButton=ref<HTMLElement>();
async function toggleCollapsed(){markerOpen.value=null;moreOpen.value=false;collapsed.value=!collapsed.value;await nextTick();collapseButton.value?.querySelector<HTMLButtonElement>('button')?.focus();}
const requestedPosition=ref<number|null>(null);
const records=ref<KnowledgeHistoryRecord[]>([]),head=ref(''),cursor=ref<string|null>(null),position=ref(-1),playing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),speed=ref('1000'),diff=ref<KnowledgeDiff>(),filter=ref(''),kind=ref(''),date=ref('');
let alive=true,epoch=0,timer:ReturnType<typeof setTimeout>|undefined,scrubTimer:ReturnType<typeof setTimeout>|undefined;const prepared=new Map<string,KnowledgeIndex>(),diffs=new Map<string,KnowledgeDiff>(),pending=new Map<string,Promise<{index:KnowledgeIndex;diff:KnowledgeDiff}>>();let preparationEpoch=0;
watch(playing,value=>emit('playing',value),{flush:'sync'});defineExpose({stop});
const chronological=computed(()=>[...records.value].reverse()),changes=computed(()=>diff.value?.changes.filter(c=>(!kind.value||c.kind===kind.value)&&`${c.path} ${c.entry.title} ${c.entry.featureId??''} ${c.entry.area??''}`.toLowerCase().includes(filter.value.toLowerCase()))??[]);
const historyNote=ref(''),historySource=ref(''),markerOpen=ref<number|null>(null);
const rail=ref<HTMLElement>(),railWidth=ref(800);let railObserver:ResizeObserver|undefined;
const viewMode=computed({get:()=>props.follow?'focus':props.overview!==false?'overview':'free',set:(value:string)=>{emit('update:follow',value==='focus');emit('update:overview',value==='overview');}});
const decisionFrames=computed(()=>chronological.value.map((record,index)=>({record,index})).filter(x=>(x.record.decisionCount??0)>0));
const markerGroups=computed(()=>{const slots=Math.max(1,Math.floor(railWidth.value/150)),bins=new Map<number,typeof decisionFrames.value>();for(const item of decisionFrames.value){const key=Math.min(slots-1,Math.floor(item.index/Math.max(1,chronological.value.length)*slots));bins.set(key,[...(bins.get(key)??[]),item]);}return {slots,items:[...bins].map(([slot,items])=>({slot,items}))};});
const frameSummary=computed(()=>diff.value?['added','modified','deleted','renamed'].map(kind=>({kind,count:diff.value!.changes.filter(c=>c.kind===kind).length})).filter(x=>x.count):[]);
const labels:Record<string,string>={added:'新增',modified:'修改',deleted:'删除',renamed:'重命名'};
function dateLabel(value?:string){return value?value.slice(0,10):'—';}
async function load(){const valid=request.capture();try{const h=await request.invoke<KnowledgeHistory>('knowledgeChanges',{projectId:props.projectId,granularity:'pull-request',...(head.value?{head:head.value}:{}),...(cursor.value?{cursor:cursor.value}:{})});if(!alive||!valid())return;const current=chronological.value[position.value]?.id;historySource.value=h.source??'';notice.value='';historyNote.value=h.source==='git'?'每一帧对应一次可识别的 PR 合并，普通提交不单独成帧。未带 PR 标识的合并不纳入回放。':'';head.value=h.head;records.value.push(...h.records);cursor.value=h.nextCursor;if(current)position.value=chronological.value.findIndex(r=>r.id===current);if(!h.complete)notice.value+=h.source==='observations'?'此项目没有可用 Git 历史，仅展示首次索引后的观察记录。':'历史不完整：仅展示本地可读取的合并记录。';}catch{if(alive)error.value='历史读取失败，请重试。';}}
async function prepare(record:KnowledgeHistoryRecord,generation:number){if(prepared.has(record.id))return prepared.get(record.id)!;const valid=request.capture();let first=true;while(alive&&generation===preparationEpoch&&valid()){const index=await request.invoke<KnowledgeIndex>('knowledgeSnapshot',{projectId:props.projectId,head:head.value,revision:record.id,...(first?{retry:true}:{})});first=false;if(!alive||generation!==preparationEpoch||!valid())throw Error('stale');if(index.state==='error')throw Error('failed');if(index.state==='ready'&&index.snapshotId){prepared.set(record.id,index);return index;}await new Promise(r=>setTimeout(r,350));}throw Error('stale');}
function frame(record:KnowledgeHistoryRecord){const existing=pending.get(record.id);if(existing)return existing;const generation=preparationEpoch,valid=request.capture();const task=prepare(record,generation).then(async index=>{const [,diff]=await Promise.all([props.prepareData?.(index),diffs.has(record.id)?Promise.resolve(diffs.get(record.id)!):request.invoke<KnowledgeDiff>('knowledgeDiff',{projectId:props.projectId,head:head.value,revision:record.id})]);return {index,diff};}).then(({index,diff})=>{if(!alive||generation!==preparationEpoch||!valid())throw Error('stale');diffs.delete(record.id);diffs.set(record.id,diff);while(diffs.size>3)diffs.delete(diffs.keys().next().value!);return {index,diff};}).finally(()=>{if(pending.get(record.id)===task)pending.delete(record.id);});pending.set(record.id,task);return task;}
async function select(i:number,play=false){clearTimeout(scrubTimer);clearTimeout(timer);if(!play)playing.value=false;const token=++epoch,record=chronological.value[i],valid=request.capture();if(!record)return;const current=()=>alive&&token===epoch&&valid(),started=performance.now();busy.value=true;error.value='';try{
 const ready=frame(record),next=chronological.value[i+1];if(next)void frame(next).catch(()=>{});const {index,diff:nextDiff}=await ready;if(!current())return;
 if(props.presentFrame)await props.presentFrame(index,nextDiff,props.follow!==false,current);else{emit('snapshot',index);for(let attempt=0;current()&&(props.activeSnapshot!==index.snapshotId||(props.renderedSnapshot!==undefined&&props.renderedSnapshot!==index.snapshotId));attempt++){if(attempt>200)throw Error('snapshot_timeout');await new Promise(r=>setTimeout(r,50));}}
 if(!current())return;position.value=i;requestedPosition.value=null;diff.value=nextDiff;if(playing.value&&next)timer=setTimeout(()=>void select(i+1,true),Math.max(0,Number(speed.value)-(performance.now()-started)));else playing.value=false;
 }catch{if(current()){playing.value=false;error.value='历史快照未能准备完成，已停止播放。';}}finally{if(current()){busy.value=false;requestedPosition.value=null;}}}
function scrub(i:number){stop();requestedPosition.value=i;busy.value=true;scrubTimer=setTimeout(()=>void select(i),100);}
function stop(){requestedPosition.value=null;playing.value=false;preparationEpoch++;pending.clear();emit('stop');clearTimeout(scrubTimer);clearTimeout(timer);epoch++;busy.value=false;}
function latest(){stop();position.value=-1;diff.value=undefined;emit('latest');}
async function play(){if(playing.value){stop();return;}const token=epoch;playing.value=true;while(cursor.value&&alive&&token===epoch){await load();if(error.value){stop();return;}}if(!alive||token!==epoch)return;void select(position.value<0||position.value>=chronological.value.length-1?0:position.value+1,true);}
function openChange(c:KnowledgeChange){const id=c.kind==='deleted'?diff.value?.beforeSnapshotId:diff.value?.afterSnapshotId;if(id)emit('open',id,c.path);}
function locateDate(value=date.value){const i=chronological.value.findIndex(r=>r.at.slice(0,10)>=value);if(i>=0)void select(i);}
watch([()=>props.activeCommit,chronological],()=>{if(!busy.value&&!playing.value&&props.activeCommit)position.value=chronological.value.findIndex(r=>r.id===props.activeCommit);});
function visibility(){if(document.hidden)stop();}
onMounted(()=>{railObserver=new ResizeObserver(entries=>{railWidth.value=entries[0]?.contentRect.width??800;});if(rail.value)railObserver.observe(rail.value);void load();document.addEventListener('visibilitychange',visibility);});onBeforeUnmount(()=>{railObserver?.disconnect();alive=false;stop();document.removeEventListener('visibilitychange',visibility);});
</script>
<template><section class="kb-timeline" :class="{collapsed}" aria-label="知识更新与时间轴" data-preserve-history-view>
 <header class="kb-player-heading"><Button v-if="collapsed" :disabled="!records.length" @click="play">{{playing?'暂停':'播放'}}</Button><strong v-else>知识演变</strong><span v-if="position>=0&&chronological[position]?.pullRequest" class="kb-player-pr">PR #{{chronological[position].pullRequest}}</span><span class="kb-player-date">{{position<0?'当前工作区':dateLabel(chronological[position]?.at)}}</span><span class="kb-player-event" :title="safe(chronological[position]?.title)">{{busy?'缓冲中…':playing?'播放中 · '+safe(chronological[position]?.title):position<0?'探索知识的形成与变化':safe(chronological[position]?.title)}}</span><progress v-if="collapsed" aria-label="历史播放进度" :value="position<0?0:position+1" :max="Math.max(1,records.length)"/><span ref="collapseButton"><Button variant="ghost" size="sm" :data-expand-player="collapsed?true:undefined" :aria-expanded="!collapsed" :aria-label="collapsed?'展开历史回放':'收起历史回放'" @click="toggleCollapsed">{{collapsed?'展开':'收起'}}</Button></span></header>
 <div v-show="!collapsed" class="kb-time-controls"><Button :disabled="!records.length" @click="play">{{playing?'暂停':'播放主线历史'}}</Button><Button variant="outline" :disabled="position<=0" @click="select(position-1)">上一步</Button><Button variant="outline" :disabled="position>=records.length-1" @click="select(position+1)">下一步</Button><NativeSelect v-model="speed" aria-label="回放速度"><option value="2000">0.5×</option><option value="1000">1×</option><option value="500">2×</option></NativeSelect><NativeSelect v-model="viewMode" aria-label="回放视角"><option value="overview">全局总览</option><option value="focus">聚焦跟踪</option><option value="free">自由浏览</option></NativeSelect><Button variant="ghost" @click="latest">返回最新</Button><Popover v-model:open="moreOpen" label="回放详情与设置"><template #trigger><Button variant="ghost" aria-label="更多回放选项">更多</Button></template><div class="kb-player-more"><p v-if="historyNote">{{historyNote}}</p> <div class="kb-frame-summary"><span v-for="item in frameSummary" :key="item.kind">{{labels[item.kind]}} {{item.count}}</span><span v-if="diff">关系 +{{diff.relationsAdded?.length??0}} / −{{diff.relationsRemoved?.length??0}}</span><span v-if="position>=0&&chronological[position]?.decisionCount" class="kb-decision-current">◆ 本帧含 {{chronological[position].decisionCount}} 处决策文档变动</span></div>
 <div class="kb-time-secondary"><span>{{viewMode==='overview'?'沿用进入回放时的星图与视角；历史独有知识在外围补充，可按需聚焦。':viewMode==='focus'?'镜头放大跟随主要变化；手动拖动切换自由浏览。':'自由浏览保留手动视角。'}}</span><Input v-model="date" type="date" aria-label="定位历史日期" @change="locateDate(($event.target as HTMLInputElement).value)"/><Button v-if="cursor" variant="outline" size="sm" @click="load">加载更早历史</Button></div>
<details><summary>知识更新列表</summary><div class="kb-time-controls"><Input v-model="filter" aria-label="筛选知识更新" placeholder="Feature、知识区或路径"/><NativeSelect v-model="kind" aria-label="变更类型"><option value="">全部变更</option><option value="added">新增</option><option value="modified">修改</option><option value="deleted">删除</option><option value="renamed">重命名</option></NativeSelect></div><p v-if="diff">关系新增 {{diff.relationsAdded?.length??0}} · 关系删除 {{diff.relationsRemoved?.length??0}}</p><div v-if="diff" class="kb-change-list"><div v-for="c in changes" :key="c.path"><span>{{({added:'新增',modified:'修改',deleted:'删除',renamed:'重命名'} as Record<string,string>)[c.kind]}}</span><Button variant="link" @click="openChange(c)">{{safe(c.entry.title)}} · {{safe(c.path)}}</Button><Button variant="ghost" @click="emit('compare',diff.beforeSnapshotId,diff.afterSnapshotId,c.path,c.previousPath)">对比</Button></div><p v-if="!changes.length">此状态无匹配的文档变化。</p></div><div class="kb-commits"><Button v-for="r in records" :key="r.id" variant="ghost" @click="select(chronological.findIndex(c=>c.id===r.id))">{{safe(r.at)}} · {{safe(r.title)}}</Button></div></details></div></Popover></div>
 <div v-show="!collapsed" ref="rail" class="kb-history-rail"><div class="kb-decision-heading"><strong>决策变更</strong><span>{{decisionFrames.length}} 个历史节点 · 根据 decisions/ 文档识别</span></div>
  <div v-if="decisionFrames.length" class="kb-decision-markers" :style="{gridTemplateColumns:'repeat('+markerGroups.slots+',minmax(0,1fr))'}">
   <div v-for="group in markerGroups.items" :key="group.slot" :style="{gridColumn:String(group.slot+1)}"><Popover :open="markerOpen===group.slot" @update:open="markerOpen=$event?group.slot:null" label="决策历史节点"><template #trigger><Button variant="outline" size="sm" class="kb-decision-marker" :title="safe(group.items.map(item=>item.record.at+' · '+item.record.title).join('\n'))" :aria-label="'决策变更：'+group.items.length+' 个历史节点'">◆ 决策 · {{group.items.length===1?safe(group.items[0].record.decisionPaths?.[0]?.split('/').at(-1)?.replace(/\.md$/i,'')??group.items[0].record.title):group.items.length+' 帧'}}</Button></template><div class="kb-decision-options"><strong>决策文档变更</strong><Button v-for="item in group.items" :key="item.record.id" variant="ghost" @click="markerOpen=null;select(item.index)"><span>{{dateLabel(item.record.at)}} · {{safe(item.record.title)}}</span><small>{{item.record.decisionCount}} 处变动 · 第 {{item.index+1}} 步</small></Button></div></Popover></div>
  </div><p v-else class="kb-rail-empty">{{historySource==='observations'?'观察记录不提供 Git 决策标记':records.length&&!records.every(r=>typeof r.decisionCount==='number')?'当前历史未提供决策标记':records.length?'已加载历史中没有决策文档变更':historySource==='git'?'未发现可识别的 PR 合并记录':'正在读取历史…'}}</p>
  <div class="kb-decision-ticks" aria-hidden="true"><i v-for="group in markerGroups.items" :key="group.slot" :style="{left:100*group.items[0].index/Math.max(1,records.length-1)+'%',width:100*(group.items.at(-1)!.index-group.items[0].index)/Math.max(1,records.length-1)+'%'}"/></div>
  <input v-if="records.length" type="range" aria-label="知识历史时间轴" :aria-valuetext="position<0?'当前工作区':'第 '+(position+1)+' 步：'+safe(chronological[position]?.title)" :min="0" :max="records.length-1" :value="requestedPosition??Math.max(0,position)" @input="scrub(Number(($event.target as HTMLInputElement).value))"/>
  <div class="kb-rail-dates"><span>{{dateLabel(chronological[0]?.at)}}</span><span>{{position<0?'当前工作区':(position+1)+' / '+records.length}} · {{historySource==='observations'?'按观察顺序':'按 PR 合并顺序'}}</span><span>{{dateLabel(chronological.at(-1)?.at)}}</span></div>
 </div>
 <p class="kb-frame-title" role="status">{{position<0?(activeCommit?'历史版本 '+safe(activeCommit):'当前工作区（含未提交变化）'):safe(chronological[position]?.title)}}<span>{{position<0?'':safe(chronological[position]?.at)}} · 已加载 {{records.length}} 个状态<span v-if="busy"> · 缓冲中…</span></span></p>
 <StatusNotice v-if="notice" tone="warning">{{notice}}</StatusNotice><StatusNotice v-if="error" tone="error">{{error}}<Button @click="error='';load()">重试</Button></StatusNotice></section></template>
<style scoped>.kb-timeline{padding:16px;margin-top:16px;border:1px solid var(--ocp-border);border-radius:10px;font-size:12px}.kb-time-controls{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:center}.kb-time-controls input[type=date]{width:160px}.kb-timeline input[type=range]{width:100%;height:32px;accent-color:var(--ocp-primary);cursor:pointer;margin:8px 0}.kb-timeline input:not([type=range]){background:var(--ocp-background);color:inherit;border:1px solid var(--ocp-border);border-radius:6px;padding:7px}.kb-commits{display:grid;max-height:240px;overflow:auto}.kb-commits button{justify-content:flex-start;height:auto;text-align:left;white-space:normal}.kb-change-list{max-height:300px;overflow:auto}.kb-change-list>div{display:flex;align-items:center;gap:8px}.kb-change-list button{white-space:normal;height:auto}summary{cursor:pointer}.kb-decision-ticks{position:relative;height:10px;margin:6px 8px -6px}.kb-decision-ticks i{position:absolute;min-width:4px;height:8px;border-radius:3px;background:var(--ocp-primary)}.kb-history-rail{border:1px solid var(--ocp-border);border-radius:12px;padding:16px;margin:14px 0;background:color-mix(in srgb,var(--ocp-foreground) 3%,var(--ocp-background))}.kb-decision-heading,.kb-rail-dates{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.kb-decision-heading span,.kb-rail-dates{font-size:12px;opacity:.75}.kb-decision-markers{display:grid;gap:8px;margin-top:14px;min-height:32px}.kb-decision-marker{width:100%;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block}.kb-decision-options{display:grid;max-height:280px;overflow:auto;gap:6px}.kb-decision-options button{display:grid;height:auto;text-align:left;white-space:normal;justify-content:start}.kb-decision-options small{opacity:.7}.kb-rail-empty{font-size:12px;opacity:.7;margin:12px 0}.kb-frame-title{font-size:17px;font-weight:600;line-height:1.5;margin:14px 0 8px;overflow-wrap:anywhere}.kb-frame-title>span{display:block;font-size:12px;font-weight:normal;opacity:.7}.kb-frame-summary{display:flex;gap:8px;flex-wrap:wrap}.kb-frame-summary>span{padding:4px 8px;border:1px solid var(--ocp-border);border-radius:6px}.kb-decision-current{color:var(--ocp-primary)}.kb-time-secondary{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:14px 0;color:var(--ocp-muted)}.kb-time-secondary>span{flex:1;min-width:180px;line-height:1.6}.kb-time-secondary input{width:160px}.kb-time-controls select{width:auto}.kb-timeline details{border-top:1px solid var(--ocp-border);padding-top:12px}.kb-timeline summary{font-size:13px}.kb-time-controls button{flex-shrink:0}@media(max-width:600px){.kb-history-rail{padding:10px}.kb-frame-title{font-size:16px}.kb-time-controls{gap:6px}.kb-time-controls button{padding-inline:10px}}

.kb-timeline{padding:14px 20px;margin:0;border-radius:16px;background:var(--ocp-background);color:var(--ocp-foreground);box-shadow:0 12px 36px #0003;font-size:14px;max-height:min(420px,65vh);overflow:auto;overscroll-behavior:contain}.kb-player-heading{display:flex;align-items:center;gap:14px;margin-bottom:12px;padding-bottom:10px;border-bottom:1px solid var(--ocp-border);min-width:0}.kb-player-heading strong{font-size:17px;white-space:nowrap}.kb-player-date{font-size:13px;white-space:nowrap}.kb-player-event{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:14px;color:var(--ocp-muted)}.kb-time-controls{gap:6px;margin-bottom:8px}.kb-history-rail{border:0;border-radius:0;background:none;padding:0;margin:0}.kb-decision-heading{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.kb-decision-markers{margin-top:8px;min-height:28px}.kb-timeline input[type=range]{margin:0;height:28px}.kb-rail-dates{font-size:11px}.kb-frame-title{position:absolute;width:1px;height:1px;margin:0;overflow:hidden;clip-path:inset(50%)}.kb-player-more{font-size:14px;min-width:0}.kb-player-more .kb-time-secondary{display:grid}.kb-player-more .kb-time-secondary input{width:100%}.kb-player-more .kb-time-controls{display:grid}.kb-player-more .kb-time-controls input{min-width:0}.kb-player-more .kb-change-list>div{flex-wrap:wrap}.kb-player-more .kb-change-list button{overflow-wrap:anywhere}.kb-timeline.collapsed{width:min(480px,100%);margin-inline:auto;border-radius:14px;padding:8px 10px}.collapsed .kb-player-heading{margin:0;padding:0;border:0;gap:10px}.collapsed .kb-player-event{font-size:12px}.kb-player-heading progress{width:64px;height:5px;accent-color:var(--ocp-primary);flex-shrink:0}.collapsed .kb-player-date{font-size:12px}.kb-player-heading progress{appearance:none;border:0;border-radius:8px;overflow:hidden;background:var(--ocp-border)}.kb-player-heading progress::-webkit-progress-bar{background:var(--ocp-border);border-radius:8px}.kb-player-heading progress::-webkit-progress-value{background:var(--ocp-primary);border-radius:8px}.kb-player-heading progress::-moz-progress-bar{background:var(--ocp-primary);border-radius:8px}
@media(max-width:600px){.kb-timeline{padding:10px 12px;max-height:55vh}.kb-player-heading{gap:8px;margin-bottom:8px;padding-bottom:6px}.kb-player-heading strong{font-size:15px}.kb-player-event{display:none}.kb-player-date{flex:1}.kb-time-controls{gap:4px}.kb-time-controls button{min-height:34px;padding-inline:8px}.kb-time-controls select{max-width:110px}.kb-rail-dates span:nth-child(2){display:none}.kb-decision-markers{gap:6px}.kb-timeline.collapsed{padding:8px}.kb-player-heading progress{width:42px}}
</style>
